// Runtime transport only: keep stage art independent of interactive chrome.
const THEATER_TRANSPORT_CSS=`
.shell[data-art] > :is(.head,.foot) button.icon{background:transparent;border:0;box-shadow:none;color:var(--chrome-ink);border-radius:8px;padding:9px;min-width:44px;min-height:44px}
.shell[data-art] > :is(.head,.foot) button.icon:is(:hover,[aria-pressed=true]){background:var(--chrome-hover);color:var(--chrome-hoverInk)}
.shell[data-art] > :is(.head,.foot) button.icon:disabled{background:transparent;color:var(--chrome-muted);opacity:.4}
.shell[data-art] > :is(.head,.foot) button.icon:focus-visible{outline:2px solid var(--chrome-accent);outline-offset:-3px}
.shell[data-art] > .foot button.next{border:0;border-radius:8px;min-height:44px;padding:9px 14px}
.shell[data-art] > .head,.shell[data-art] > .foot{border-color:transparent;gap:8px;padding-block:6px}
.shell[data-art] > .head{padding-top:max(6px,env(safe-area-inset-top))}.shell[data-art] > .foot{padding-bottom:max(6px,env(safe-area-inset-bottom))}
.shell > .head .live-head{gap:0}.shell > .head [data-head-tools]{gap:3px!important}.shell > .head .live-head output{font-variant-numeric:tabular-nums;min-width:26px}
.shell[data-art] > .head [data-action=live-stop]{color:#f3a4a4}
.shell[data-art] > .foot .tools,.shell[data-art] > .foot .transport{gap:3px}
.shell[data-art] > .foot .meter{height:3px;background:color-mix(in srgb,var(--chrome-ink) 20%,transparent);border-radius:3px}.shell[data-art] > .foot .meter span{mask-image:none}
.shell[data-art] > .panel .refresh-panel{display:flex;align-items:center;gap:10px;justify-content:flex-start;width:100%}
/* One live toolbar, re-used in focus mode. No duplicated command state or buttons. */
.shell[data-art][data-live-enabled=true][data-chrome=hidden] > .head{display:flex;position:absolute;top:max(7px,env(safe-area-inset-top));right:60px;width:auto;height:auto;padding:0;background:transparent;border:0;z-index:6;gap:0;filter:drop-shadow(0 1px 3px #000) drop-shadow(0 0 5px #000)}
.shell[data-live-enabled=true][data-chrome=hidden] > .head :is(.brand,.spacer,[data-action=refresh],[data-action=exit],[data-action=live-reply],[data-action=live-regenerate]){display:none!important}
.shell[data-art][data-live-enabled=true][data-chrome=hidden] > .head button.icon,.shell[data-art][data-live-enabled=true][data-chrome=hidden] > .head button.icon:hover{background:transparent;border:0;color:#fff;box-shadow:none}
.shell[data-live-enabled=true][data-chrome=hidden] > .head .live-swipe-count{color:#fff}
.shell[data-art][data-live-enabled=true][data-chrome=hidden] > .head [data-action=live-stop]{color:#ffb2b2}
.shell[data-art][data-chrome=hidden] > button.icon.restore{top:max(7px,env(safe-area-inset-top));right:10px}
@media(hover:hover) and (pointer:fine){.shell[data-live-enabled=true][data-chrome=hidden] > .head{opacity:0;transition:opacity .18s ease}.shell[data-live-enabled=true][data-chrome=hidden] > .head:is(:hover,:focus-within),.shell[data-live-enabled=true][data-chrome=hidden][data-live-generating=true] > .head{opacity:1}}
@media(max-width:600px){
 .shell[data-art] > .head,.shell[data-art] > .foot{padding-inline:8px;gap:4px}
 .shell[data-art] > .head .brand strong{font-size:12px;line-height:1.15;white-space:normal;overflow:hidden;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2}.shell[data-art] > .head .brand>div{min-width:0}.shell[data-art] > .head .scope{font-size:10px;line-height:1.2;max-width:100%}.shell[data-live-enabled=true] > .head .brand{flex:1}.shell[data-live-enabled=true] > .head>.spacer{display:none}
 .shell[data-art] > .head button.icon,.shell[data-art] > .foot button.icon{width:40px;min-width:40px;height:40px;min-height:40px;padding:8px}.shell[data-art] > .head button.icon svg,.shell[data-art] > .foot button.icon svg{width:20px;height:20px}
 .shell[data-art] > .head [data-head-tools]{gap:0!important;flex:none}.shell[data-art] > .head .live-head{gap:0}.shell[data-art] > .head .live-head output{min-width:24px}
 .shell[data-art] > .foot{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;justify-items:stretch;row-gap:3px}
 .shell[data-art] > .foot .progress{grid-column:1/-1;grid-row:1;gap:3px;min-width:0}.shell[data-art] > .foot .counter{font-size:10px;line-height:1.2}
 .shell[data-art] > .foot .transport{grid-column:1;grid-row:2;gap:0}.shell[data-art] > .foot .tools{grid-column:2;grid-row:2;justify-content:flex-end;gap:0}
 .shell[data-art] > .foot button.next{min-width:40px;width:40px;height:40px;min-height:40px;padding:8px;gap:0!important}.shell[data-art] > .foot button.next .next-label{display:none}.shell[data-art] > .foot button.next:is([data-live-label=Reply],[data-live-label=Wait],[data-live-label=Reveal]) .next-label{display:block;font-size:10px;line-height:1}.shell[data-art] > .foot button.next:is([data-live-label=Reply],[data-live-label=Wait],[data-live-label=Reveal]) svg{display:none}
 .shell[data-art] > .foot .live-note{grid-column:1/-1;margin:0;font-size:10px;line-height:1.2}
 .shell[data-art][data-chrome=hidden] > .foot{display:none}
 .shell[data-art=celluloid] .stage{border-block-width:3px}
 .shell[data-card-dock=true]:not([data-native=true]) .frame[data-kind=cast]>.hint,.shell[data-native=true] .frame[data-kind=cast]>.hint{bottom:auto;top:-15px;right:8px;min-height:0}.shell[data-card-dock=true] .frame[data-kind=cast]>.hint .hint-copy,.shell[data-native=true] .frame[data-kind=cast]>.hint .hint-copy{display:none}
 .shell[data-art] .frame[data-kind=cast]>.page-label{font-size:9px;letter-spacing:.14em}
}
@media(min-width:351px) and (max-width:600px){.shell[data-art] > .head button.icon,.shell[data-art] > .foot button.icon,.shell[data-art] > .foot button.next{width:44px;min-width:44px;height:44px;min-height:44px}}
@media(max-width:350px){.shell[data-art] > .head,.shell[data-art] > .foot{padding-inline:4px}.shell[data-art] > .head .scope{display:none}.shell[data-art] > .foot button.icon,.shell[data-art] > .foot button.next{width:40px;min-width:40px}}
@media(prefers-reduced-motion:reduce){.shell[data-live-enabled=true][data-chrome=hidden] > .head{transition:none}}
`
// Only the Theater's full-size projection, never regular chat or picker thumbnails.
const THEATER_MOBILE_CARD_CSS=`
@media(max-width:600px){
 :host([data-compact][data-density=graphic]) .ss-cast-design [data-swarm-cast-dialogue][data-th-graphic-text]{font-size:calc(max(14px,calc(var(--th-graphic-size) * var(--th-caption-scale,1))) * var(--art-graphic-dialogue,1))!important;line-height:1.5}
 :host([data-dock=true]) .ss-cast-design .atelier-overlap .stage-actor{width:min(92%,420px);height:clamp(220px,52dvh,500px)}
}
`

const THEATER_SCENERY_INDEX_CSS=`
.shell[data-art][data-manual-scenery=true] .scenery{opacity:1}
.panel .scenery-sources,.panel .scenery-assets{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.shell[data-art] .panel .scenery-sources button,.shell[data-art] .panel .scenery-assets button{display:flex;flex-direction:column;align-items:flex-start;gap:4px;text-align:left;min-width:0;padding:9px;overflow-wrap:anywhere;background:var(--ui-bg)}
.panel .scenery-sources small,.panel .scenery-assets small{color:var(--ui-muted);font-size:11px}.panel .scenery-sources strong,.panel .scenery-assets strong{font-size:13px}
.shell[data-art] .panel .scenery-sources button[aria-pressed=true],.shell[data-art] .panel .scenery-assets button[aria-pressed=true]{border-color:var(--ui-accent,#c7b1f4);background:#393145}
.panel .scenery-assets img{width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:5px;background:#14131b}.panel .scenery-assets button[data-missing=true]::before{content:'Image unavailable';font-size:11px;color:var(--ui-muted)}
.panel .scenery-library-toolbar,.panel .scenery-filter{display:flex;gap:8px;align-items:center;justify-content:space-between;min-width:0}.panel .scenery-filter input{flex:1;width:0;min-width:0;padding:9px;border-radius:7px}.panel .scenery-filter select{max-width:48%}.panel .scenery-pin{display:flex;align-items:center;justify-content:center;gap:8px;min-height:40px}
.panel .index-overview{font-size:12px;color:var(--ui-muted);margin:0}.panel .index-group{border:1px solid var(--ui-line);border-radius:10px;overflow:hidden;background:var(--ui-bg)}.panel .index-group[data-current=true]{border-color:var(--ui-accent,#c7b1f4)}
.panel .index-heading{display:grid;grid-template-columns:minmax(0,1fr) 58px;align-items:stretch}.shell[data-art] .panel .index-start:not(.art-mini *),.shell[data-art] .panel .index-toggle:not(.art-mini *){border:0;border-radius:0;background:transparent;min-width:0;color:var(--ui-ink,#f3eff5)}.panel .index-start{display:grid;gap:4px;text-align:left;padding:12px 14px}.panel .index-start strong{font-size:15px;overflow-wrap:anywhere}.panel .index-role{font-size:10px;text-transform:uppercase;letter-spacing:.07em;color:var(--ui-muted)}.panel .index-group[data-role=user] .index-role{color:#cbb7f2}.panel .index-start small{font-size:12px;color:var(--ui-muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.panel .index-toggle{display:flex;align-items:center;justify-content:center;gap:3px;font-size:11px}.panel .index-toggle[aria-expanded=true] svg{transform:rotate(90deg)}.panel .index-single{display:grid;place-items:center;font-size:11px;color:var(--ui-muted)}.panel .index-children{padding:6px;border-top:1px solid var(--ui-line);display:grid;gap:4px}.panel .index-children[hidden]{display:none!important}.shell[data-art] .panel .index-entry{border:0;padding:9px 10px;background:transparent}.shell[data-art] .panel :is(.index-entry,.index-start,.index-toggle):hover,.shell[data-art] .panel :is(.index-entry,.index-start)[aria-current=true]{background:#393145}.panel .index-entry small{font-size:10px}.panel .index-entry>span:last-child{min-width:0;overflow-wrap:anywhere}
@media(max-width:600px){.panel .scenery-filter{flex-wrap:wrap}.panel .scenery-filter input{flex:1 1 100%;width:100%}.panel .scenery-filter select{width:100%;max-width:none}.panel .scenery-assets,.panel .scenery-sources{gap:6px}.panel .index-heading{grid-template-columns:minmax(0,1fr) 50px}.panel .index-start{padding:10px 12px}.panel .index-toggle{min-height:44px}}

/* Quick director console: compact stage entry points and immediate playback settings. */
.panel[data-panel=settings] > .panel-body{gap:11px}.panel .quick-section{display:grid;gap:9px}.panel .quick-heading{display:grid;gap:3px}.panel .quick-heading h3{font:650 14px/1.3 system-ui,sans-serif;margin:0;color:var(--ui-ink)}.panel .quick-heading p{font-size:12px;line-height:1.4;color:var(--ui-muted);margin:0}
.panel .quick-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-auto-rows:1fr;gap:6px}.shell[data-art] > .panel .quick-entry:not(.art-mini *){display:grid;grid-template-columns:22px minmax(0,1fr);gap:9px;align-items:center;text-align:left;min-height:54px;padding:8px;background:var(--ui-surface);border-color:transparent;box-shadow:none}.panel .quick-entry>svg{width:21px;height:21px;color:var(--ui-accent)}.panel .quick-entry-copy{min-width:0;display:grid;gap:3px}.panel .quick-entry-copy strong{font-size:13px;line-height:1.2}.panel .quick-entry-copy small{font-size:11px;line-height:1.3;color:var(--ui-muted);overflow-wrap:anywhere}.shell[data-art] > .panel .quick-entry:not(.art-mini *):hover{border-color:transparent;background:var(--ui-raised)}
.panel .quick-field,.panel .quick-range{display:grid;gap:6px}.panel .quick-label{font-size:12px;font-weight:600;color:var(--ui-ink)}.panel .quick-segments{display:grid;grid-template-columns:repeat(var(--segments),minmax(0,1fr));gap:3px;padding:3px;background:var(--ui-bg);border-radius:9px}.shell[data-art] > .panel .quick-choice:not(.art-mini *){font-size:12px;min-height:36px;padding:6px 3px;line-height:1.2;background:transparent;border-color:transparent;border-radius:6px;overflow-wrap:anywhere}.shell[data-art] > .panel .quick-choice:not(.art-mini *)[aria-pressed=true]{background:var(--ui-raised);color:var(--ui-accent);border-color:transparent;box-shadow:none;font-weight:650}.panel .quick-range-heading{display:flex;align-items:center;justify-content:space-between;gap:8px}.panel .quick-range output{font-size:12px;color:var(--ui-accent);font-variant-numeric:tabular-nums}.panel .quick-range input{width:100%;margin:0}.panel .quick-defaults{border-top:1px solid var(--ui-line);border-bottom:1px solid var(--ui-line);padding:10px 0}.panel .quick-defaults summary{cursor:pointer;font-size:13px;font-weight:600;min-height:40px;padding:3px 2px;line-height:1.4}.panel .quick-defaults summary small{display:block;font-size:11px;font-weight:400;color:var(--ui-muted);padding-left:15px}.panel .quick-defaults-body{display:grid;gap:12px;padding:8px 2px 4px}.panel .quick-scene-actions{display:flex;justify-content:flex-end;gap:5px}.shell[data-art] > .panel .quick-link:not(.art-mini *){display:inline-flex;align-items:center;justify-content:center;gap:7px;background:transparent;border-color:transparent;min-height:40px;font-size:12px;color:var(--ui-muted);padding:7px 10px}.panel .quick-link svg{width:17px;height:17px}.shell[data-art] > .panel .quick-link:not(.art-mini *)[aria-pressed=true]{color:var(--ui-accent);box-shadow:none}.panel .quick-refresh{align-self:flex-start}.shell[data-art] > .panel[data-panel=settings] .art-open{padding:10px;background:var(--ui-surface);border-color:transparent}.panel[data-panel=settings] .art-open strong{font-size:13px}.panel[data-panel=settings] .art-open small{font-size:11px}
@media(max-width:600px){.panel .quick-section{gap:10px}.shell[data-art] > .panel .quick-entry:not(.art-mini *){min-height:54px;padding:7px;gap:6px;grid-template-columns:19px minmax(0,1fr)}.panel .quick-entry>svg{width:19px;height:19px}.panel .quick-entry-copy strong{font-size:12px}.panel .quick-entry-copy small{font-size:10px}.shell[data-art] > .panel .quick-choice:not(.art-mini *){min-height:40px;font-size:11px}.panel .quick-heading p{font-size:11px}.panel .quick-grid{gap:5px}}
`
